    for ep in endpoints:
        try:
            records = fetch_all_pages(base_url, ep, data_key=config.get("data_key", "results"))
            for rec in records:
                result.add_success()
        except Exception as exc:
            result.add_failure(f"Failed to ingest from {ep}: {exc}")
            logger.error(f"API ingestion error for {ep}: {exc}")

